import {esc,btn,date} from './ui.mjs';
export const settingsLinks=()=>`<div class="settings-links">${btn('Команда','data-view="team"','secondary')}${btn('Состояние и копии','data-view="operations"','secondary')}</div>`;
export function teamView(s){return `<section class="page-head"><h1>Команда</h1>${btn('Настройки','data-view="settings"')}</section><p class="fine">Сотрудник сначала открывает бота и отправляет /id. Владелец остаётся администратором.</p><div class="team-list">${(s.team?.members||[]).map(m=>`<article class="team-row"><div><strong>${esc(m.name)}</strong><p>${esc(m.id)} · ${m.role==='admin'?'Владелец':m.publish?'Менеджер · Threads':'Менеджер · отбор'}</p><p class="fine">${m.error?'Бот недоступен: '+esc(m.error):m.lastSeen?'Бот открыт '+date(m.lastSeen):'Ожидаем /start в боте'}</p></div>${m.role!=='admin'?`<div>${btn('Права',`data-member="${m.id}"`,'text')}${btn('Отозвать',`data-revoke="${m.id}"`,'text')}</div>`:''}</article>`).join('')}</div><section class="settings-section"><h2>Добавить менеджера</h2><form data-form="member" class="stack"><label>Telegram ID<input name="id" inputmode="numeric" pattern="[0-9]{1,16}" required></label><label>Имя в команде<input name="name" maxlength="80" required></label><label class="check-line"><input type="checkbox" name="publish">Разрешить публикации в Threads</label><label class="check-line"><input type="checkbox" name="confirmed" required>Подтверждаю доступ этого человека к заявкам</label>${btn('Добавить менеджера','type="submit"','primary')}<p class="form-error" role="alert"></p></form></section><details class="brief-note"><summary>История доступа</summary>${(s.team?.events||[]).map(e=>`<p>${date(e.at)} · ${esc(e.id)} · ${e.active?'доступ выдан / изменён':'доступ отозван'}${e.publish?' · Threads':''}</p>`).join('')||'<p>Изменений пока нет.</p>'}</details>`;}
export function operationsView(s){const o=s.operations||{},jobs=o.jobs||[];return `<section class="page-head"><h1>Состояние</h1>${btn('Настройки','data-view="settings"')}</section><div class="ops-grid"><section class="settings-section"><h2>Обработка</h2><dl class="account-details"><div><dt>Обработчик</dt><dd>${o.lastWorker?date(o.lastWorker):'Ожидаем запуск'}</dd></div><div><dt>Последняя оценка ИИ</dt><dd>${o.lastAi?date(o.lastAi):'Нет успешной оценки'}</dd></div><div><dt>Самое старое задание</dt><dd>${o.oldestPendingAt?date(o.oldestPendingAt):'Очередь пуста'}</dd></div></dl>${o.threadsError?`<p class="inline-error">${esc(o.threadsError)}</p>`:''}${!o.ready?'<p class="inline-error">Приём новых анкет закрыт: заполните и подтвердите условия в настройках.</p>':''}<div class="job-list">${jobs.map(j=>`<article class="team-row"><div><strong>${esc(({ai:'Оценка ИИ',telegram:'Сообщение',telegram_update:'Действие в боте'})[j.kind]||j.kind)} · ${j.status==='failed'?'Ошибка':'В очереди'}</strong><p>${esc(j.last_error||'Ожидает обработки')} · попыток ${j.attempts}</p></div>${j.status==='failed'?btn('Повторить',`data-retry-job="${j.id}"`,'secondary'):''}</article>`).join('')}</div></section><section class="settings-section"><h2>Резервные копии</h2><p>Проверенная копия создаётся автоматически каждые 24 часа. На диске сохраняются последние 14 копий.</p><p class="fine">Копии на диске приложения нужно дополнять отдельным архивом Railway Volume.</p>${o.backupError?`<p class="inline-error">${esc(o.backupError)}</p>`:''}<p class="fine">Последняя: ${o.backup?.at?date(o.backup.at):'ещё не создана'}</p>${btn('Создать копию сейчас','data-backup','primary')}<div class="backup-list">${(o.backups||[]).map(b=>`<div class="team-row"><div><strong>${date(b.at)}</strong><p>${Math.ceil(b.bytes/1024)} КБ</p></div>${btn('Скачать',`data-download="${esc(b.name)}"`,'text')}</div>`).join('')}</div></section></div>`;}
